  name: string | null;
  url: string;
  triggers: string[];
  surveyIds: string[];
  workspaceId: string;
}): Promise<void> => {
  const workspaceId = webhook.workspaceId;

  // Authorize against the workspace
  const organizationId = await getOrganizationIdFromWorkspaceId(workspaceId);
  // We need the current user context; since this is a client action wrapper,
  // we use the authenticatedActionClient pattern via a server-only helper.
  // For simplicity and consistency, we'"'ll use the internal createWebhook directly
  // and rely on the page revalidation. This function is called from client-side
  // code, so we must ensure it runs in a server context.

  // Use the internal createWebhook with a new secret
  const newSecret = generateWebhookSecret();
  const newWebhook = await createWebhook(workspaceId, {
